mkdir -p /tmp/chk && cat > /tmp/chk/check.py <<'EOF'
import json, os, re, sys, html
from html.parser import HTMLParser
root = sys.argv[1]; data = json.load(open(sys.argv[2])); B = "https://demo.example"
pages = {}
for d, _, fs in os.walk(root):
    for f in fs:
        if f.endswith(".html"):
            rel = os.path.relpath(os.path.join(d, f), root)
            url = B + "/" + (rel[:-len("index.html")] if rel.endswith("index.html") else rel)
            pages[url] = open(os.path.join(d, f)).read()
class P(HTMLParser):
    def __init__(s): super().__init__(); s.t=[]; s.intitle=False; s.titles=[]; s.links=[]; s.meta={}; s.canon=[]; s.text=[]; s.badges=0; s.lang=None
    def handle_starttag(s, tag, a):
        a = dict(a)
        if tag=="html": s.lang=a.get("lang")
        if tag=="title": s.intitle=True; s.titles.append("")
        for k in ("href","src"):
            if k in a: s.links.append(a[k])
        if tag=="link" and a.get("rel")=="canonical": s.canon.append(a["href"])
        if tag=="meta" and "property" in a: s.meta.setdefault(a["property"],[]).append(a["content"])
        if "badge" in (a.get("class") or "").split(): s.badges+=1
    def handle_endtag(s, tag):
        if tag=="title": s.intitle=False
    def handle_data(s, d):
        if s.intitle: s.titles[-1]+=d
        s.text.append(d)
errs=[]; titles={}
for url, src in pages.items():
    p=P(); p.feed(src); text=" ".join(" ".join(p.text).split())
    if p.lang!="en": errs.append((url,"lang"))
    if len(p.titles)!=1 or not p.titles[0].strip(): errs.append((url,"title"))
    t=p.titles[0]; titles.setdefault(t,[]).append(url)
    if p.canon!=[url] or p.meta.get("og:url")!=[url] or p.meta.get("og:title")!=[t] or p.meta.get("og:type")!=["website"]: errs.append((url,"meta"))
    if "&amp;" in text: errs.append((url,"double escape"))
    for l in p.links:
        if l.startswith(B): l=l[len(B):]
        if re.match(r"^[a-z]+:",l): continue
        path = l if l.startswith("/") else "/"+os.path.relpath(os.path.join(os.path.dirname(url[len(B):]+"x"), l))
        f = os.path.join(root, path.lstrip("/"))
        if path.endswith("/"): f=os.path.join(f,"index.html")
        if not os.path.isfile(f): errs.append((url,"broken "+l))
    if "/style.css" not in p.links: errs.append((url,"css"))
    for m in re.findall(r'<script type="application/ld\+json">(.*?)</script>', src, re.S): json.loads(m)
    if url==B+"/":
        if t!="Demo — dividend stocks" or f"Stocks (cycle {data['cycle_id']})" not in text: errs.append((url,"home"))
        for s in data["stocks"]:
            if f"/stocks/{s['ticker']}/" not in p.links or f"{s['name']} — {s['sector']}" not in text: errs.append((url,"home stock "+s["ticker"]))
order=[s["name"] for s in data["stocks"]]
hp=" ".join(P().text) 
for s in data["stocks"]:
    url=f"{B}/stocks/{s['ticker']}/"; src=pages.get(url)
    if src is None: errs.append((url,"missing")); continue
    p=P(); p.feed(src); text=" ".join(" ".join(p.text).split())
    if p.titles[0]!=f"{s['name']} ({s['ticker']})": errs.append((url,"stock title"))
    for x in (s["name"], s["ticker"], s["sector"]):
        if x not in text: errs.append((url,"missing "+x))
    u=s["upcoming"]
    if u:
        if f"Next dividend: {u['amount']} {u['currency']} — ex {u['ex_date']}" not in text: errs.append((url,"div"))
    elif "No upcoming dividend declared." not in text: errs.append((url,"nodiv"))
    want = 1 if (u and not u["confirmed"]) else 0
    if p.badges!=want or (want and "Estimated — not yet declared" not in text): errs.append((url,"badge"))
    if "/" not in p.links: errs.append((url,"backlink"))
for t,u in titles.items():
    if len(u)>1: errs.append((t,"dup title"))
locs=re.findall(r"<loc>(.*?)</loc>", open(os.path.join(root,"sitemap.xml")).read())
if sorted(locs)!=sorted(pages) or len(set(locs))!=len(locs): errs.append(("sitemap",locs))
r=open(os.path.join(root,"robots.txt")).read()
if B+"/sitemap.xml" not in r: errs.append(("robots",r))
print(len(pages),"pages;", errs or "ALL OK")
EOF
